/**
 * HTTP route contracts (request/response bodies). All routes identify the user via the
 * HttpOnly `cl_anon` cookie (set by POST /api/unlock). See docs/design-plan.md §4.
 */
import type { MomentView, Verdict } from "./moment";
import type { LevelInfo, LevelReward, UserSettings, BossOutcome } from "./engine";
import type { Intent, SessionSketch, SessionSummary, StoryChapter, TranscriptItem } from "./session";
import type { XpAward } from "./stream";

export const ANON_COOKIE = "cl_anon";
export const UNLOCK_PHRASE = "/co-learn";

export interface UserView {
  xp: number;
  level: LevelInfo;
  unlocks: { themes: string[]; soundPacks: string[] };
  settings: UserSettings;
}

// POST /api/unlock
export interface UnlockRequest { phrase: string }
export interface UnlockResponse { ok: true; user: UserView; sessions: SessionSummary[] }

// GET /api/user  → UserView
// PATCH /api/user  (partial settings)
export type UpdateSettingsRequest = Partial<UserSettings>;

// POST /api/session
export interface CreateSessionRequest { intent: Intent }
export interface CreateSessionResponse { sessionId: string }

// GET /api/session/[id]
export interface SessionView {
  id: string;
  title: string;
  intent: Intent;
  sketch?: SessionSketch;
  status: "active" | "wrapped";
  createdAt: number;
  endsAt: number; // createdAt + intent.minutes
  transcript: TranscriptItem[];
  moments: Record<string, MomentView>;
  bosses: Record<string, BossView>;
  chapters: Record<string, StoryChapter>;
}

// GET /api/sessions → SessionSummary[]

// POST /api/chat  (streams ChatStreamEvent NDJSON)
export type ChatRequest =
  | { sessionId: string; kind: "message"; text: string }
  | { sessionId: string; kind: "moment_response"; momentId: string } // server builds the text from the stored moment record
  | { sessionId: string; kind: "boss_result"; bossId: string }
  | { sessionId: string; kind: "continue" }; // auto-continue (e.g. after pause_turn)

// POST /api/moment/grade
export type GradeRequest =
  | { sessionId: string; momentId: string; action: "submit"; answer: string }
  | { sessionId: string; momentId: string; action: "mc"; choice: number }
  | { sessionId: string; momentId: string; action: "show_options" }
  | { sessionId: string; momentId: string; action: "skip" | "defer" | "report" };

export interface GradeResponse {
  moment: MomentView; // updated view (verdict/why/mcOptions/correctIndex as applicable)
  verdict?: Verdict;
  offerMC: boolean; // true after a miss/struggle when MC hasn't been used yet
  xp?: XpAward;
  boss?: { bossId: string; hp: number; maxHp: number; done: boolean; outcome?: BossOutcome; nextMomentId?: string };
  /** Whether the client should now POST /api/chat (moment_response or boss_result) to continue the work. */
  continueWith?: ChatRequest;
}

// POST /api/boss
export interface StartBossRequest { sessionId: string }
export interface BossView {
  id: string;
  name: string;
  ascii: "bug" | "slime" | "ghost";
  intro: string;
  hp: number;
  maxHp: number;
  momentIds: string[];
  currentMomentId?: string;
  outcome?: BossOutcome;
}
export interface StartBossResponse { boss: BossView; moments: Record<string, MomentView> }

// POST /api/wrapup
export interface WrapUpRequest { sessionId: string }
export interface WrapUpResponse {
  deferred: MomentView[]; // deferred moments to answer now (graded via /api/moment/grade)
  codex: { concept: string; summary: string; result: "strong" | "growing" | "review" }[];
  sessionXp: number;
  user: UserView;
  chapter?: StoryChapter;
  suggestions: string[];
  levelUps: { from: number; to: number; rewards: LevelReward[] }[];
}

// GET /api/story?sessionId=&trigger=  → { chapter: StoryChapter | null } (null = still generating)

// GET /api/files/[id]?sessionId=  → file bytes (ownership-checked)
/**
 * Content-generation contract (Track D implements in lib/claude/content/*).
 * Each function makes one structured Claude call (messages.parse + zodOutputFormat).
 */
import type { LearningMomentInput, Verdict } from "./moment";
import type { Intent, SessionSketch, StoryBible, StoryChapter } from "./session";
import type { BossOutcome, Familiarity } from "./engine";

export interface GradeResult {
  verdict: Verdict;
  why: string; // 1-2 sentences, encouraging, explains the reasoning (P3)
  missingPoints: string[];
  misconception?: string;
}

export interface VerifyResult {
  ok: boolean; // false → gate converts to skip("unverified")
  reason?: string;
}

export interface BossDraft {
  name: string;
  ascii: "bug" | "slime" | "ghost";
  intro: string; // 1-2 playful sentences
  questions: LearningMomentInput[]; // 2-3 linked questions, type "explain_back"/"spot_issue"/"decide" shapes reused
}

export interface WrapUpDraft {
  codex: { concept: string; summary: string; result: "strong" | "growing" | "review" }[];
  suggestions: string[]; // 2-3 "next time you could..." ideas
}

export interface ContentApi {
  gradeAnswer(input: { candidate: LearningMomentInput; answer: string }): Promise<GradeResult>;
  verifyMoment(input: { candidate: LearningMomentInput }): Promise<VerifyResult>;
  generateSketch(input: { intent: Intent }): Promise<SessionSketch>;
  generateBoss(input: {
    intent: Intent;
    familiarity: Familiarity;
    concepts: string[];
    workSummary: string; // what was built so far, incl. real metrics
    misconceptions: string[];
    targetDifficulty: number;
  }): Promise<BossDraft>;
  generateStoryBible(input: { intent: Intent }): Promise<StoryBible>;
  generateChapter(input: {
    bible: StoryBible;
    previous: Pick<StoryChapter, "title" | "summary">[];
    trigger: string;
    beat: "boss" | "wrapup";
    performance?: BossOutcome;
  }): Promise<Omit<StoryChapter, "id" | "createdAt" | "trigger">>;
  generateWrapUp(input: {
    intent: Intent;
    outcomes: { concept: string; type: string; score: number }[];
    workSummary: string;
  }): Promise<WrapUpDraft>;
}
/**
 * Pacing-engine contract (Track B implements in lib/engine/, pure + unit-tested).
 * See docs/design-plan.md §7.
 */
import type { LearningMomentInput, MomentType, Verdict } from "./moment";

export type Familiarity = "new" | "some" | "comfortable";
export type GuardrailMode = "light" | "balanced" | "strict";

export interface UserSettings {
  sound: boolean;
  volume: number; // 0..1
  theme: string; // theme id
  soundPack: string; // sound pack id
  guardrails: { enabled: boolean; mode: GuardrailMode };
}

export interface ConceptMastery {
  theta: number;
  n: number;
  lastSeen: number; // epoch ms
}
export type MasteryMap = Record<string, ConceptMastery>;

export interface Outcome {
  momentId: string;
  concept: string;
  type: MomentType | "boss";
  score: number; // 1 correct, 0.6 correct-after-MC, 0.5 partial, 0 incorrect
  at: number;
}

export type BossOutcome = "flawless" | "victory" | "retreat";
export interface BossRecord {
  id: string;
  startedAt: number;
  concepts: string[];
  outcome?: BossOutcome;
}

export interface EngineState {
  pendingMomentId?: string;
  momentsShownAt: number[]; // epoch ms of each shown moment
  turnsSinceMoment: number; // work turns since last shown moment
  conceptsSinceBoss: string[]; // distinct concepts practised since last boss
  bosses: BossRecord[];
  recentOutcomes: Outcome[]; // most recent last, capped (e.g. 20)
}

export const initialEngineState = (): EngineState => ({
  momentsShownAt: [],
  turnsSinceMoment: 0,
  conceptsSinceBoss: [],
  bosses: [],
  recentOutcomes: [],
});

export interface GateContext {
  state: EngineState;
  mastery: MasteryMap;
  settings: UserSettings;
  familiarity: Familiarity;
  now: number;
}

export type GateDecision =
  | { action: "show" }
  | { action: "defer"; reason: string }
  | { action: "skip"; reason: "one_at_a_time" | "low_value" | "mastered" | "off_band" | "cap" | "unverified" };

export type DifficultyKind = "first_exposure" | "practice" | "boss";

/** Engine summary rendered into the work model's dynamic context each turn. */
export interface EngineSummary {
  guardrails: { enabled: boolean; mode: GuardrailMode };
  valueThreshold: number;
  targetDifficulty: { firstExposure: number; practice: number }; // for a typical unseen/seen concept
  masteredConcepts: string[];
  conceptsSinceBoss: string[];
  rollingAccuracy: number | null; // over last 5 graded outcomes
  recentOutcomes: { concept: string; type: string; score: number }[]; // last 3
}

export type XpEvent =
  | { kind: "answer"; verdict: Verdict; afterMC: boolean }
  | { kind: "prediction"; verdict: Verdict }
  | { kind: "boss_hit"; partial: boolean }
  | { kind: "boss_outcome"; outcome: BossOutcome }
  | { kind: "session_complete" };

export interface LevelInfo {
  level: number;
  xp: number;
  levelStartXp: number;
  nextLevelXp: number;
}

export interface LevelReward {
  level: number;
  kind: "theme" | "sound_pack";
  id: string;
  label: string;
}

/** Signatures Track B must export from lib/engine/index.ts. */
export interface EngineApi {
  gate(candidate: LearningMomentInput, ctx: GateContext): GateDecision;
  updateMastery(prev: ConceptMastery | undefined, score: number, difficulty: number, familiarity: Familiarity, now: number): ConceptMastery;
  targetDifficulty(m: ConceptMastery | undefined, kind: DifficultyKind, familiarity: Familiarity, recent: Outcome[]): number;
  isMastered(m: ConceptMastery | undefined): boolean;
  reviewDue(m: ConceptMastery | undefined, now: number): boolean;
  bossDue(state: EngineState, now: number, sessionEndsAt: number): boolean;
  bossOutcome(hits: number, maxHits: number): BossOutcome;
  summarize(ctx: GateContext): EngineSummary;
  recordShown(state: EngineState, momentId: string, now: number): EngineState;
  recordOutcome(state: EngineState, outcome: Outcome): EngineState;
  recordWorkTurn(state: EngineState): EngineState;
  xpFor(event: XpEvent): number;
  levelFor(totalXp: number): LevelInfo;
  rewardsBetween(fromLevel: number, toLevel: number): LevelReward[];
}
export * from "./moment";
export * from "./engine";
export * from "./session";
export * from "./store";
export * from "./stream";
export * from "./api";
export * from "./content";
/**
 * Learning-moment contract: the `learning_moment` tool Claude calls during a work turn,
 * and the client-safe view of a moment. See docs/design-plan.md §6.
 */
import { z } from "zod";

export const MOMENT_TYPES = ["decide", "predict", "explain_back", "spot_issue", "fill_gap"] as const;
export type MomentType = (typeof MOMENT_TYPES)[number];

/** Input Claude supplies when it calls the `learning_moment` tool. */
export const LearningMomentInputSchema = z.object({
  type: z.enum(MOMENT_TYPES),
  concept: z.string().min(1).max(60),
  concept_card: z.string().max(600).optional(),
  question: z.string().min(1).max(600),
  ideal_answer: z.string().min(1).max(1200),
  rubric: z.object({
    key_points: z.array(z.string()).min(1).max(6),
    acceptable_variants: z.array(z.string()).max(6).optional(),
    misconceptions: z.array(z.string()).max(6).optional(),
  }),
  mc_fallback: z.object({
    options: z.array(z.string()).min(3).max(4),
    correct_index: z.number().int().min(0).max(3),
    why: z.array(z.string()).min(3).max(4),
  }),
  difficulty: z.number().int().min(1).max(5),
  first_exposure: z.boolean(),
  learning_value: z.number().int().min(1).max(5),
  value_reason: z.string().max(300),
  costly_mistake: z.boolean(),
  timing: z.enum(["before_step", "after_step"]),
});
export type LearningMomentInput = z.infer<typeof LearningMomentInputSchema>;

/** Input for `resolve_prediction`, called after real code output is available. */
export const ResolvePredictionInputSchema = z.object({
  moment_id: z.string(),
  actual_result: z.string().max(600),
  verdict: z.enum(["correct", "partial", "incorrect"]),
  why: z.string().max(600),
});
export type ResolvePredictionInput = z.infer<typeof ResolvePredictionInputSchema>;

/** Input for `milestone_reached`, called when a chunk of work completes. */
export const MilestoneInputSchema = z.object({
  label: z.string().max(120),
  summary: z.string().max(600),
  concepts_involved: z.array(z.string()).max(10),
});
export type MilestoneInput = z.infer<typeof MilestoneInputSchema>;

export type Verdict = "correct" | "partial" | "incorrect";
export type MomentStatus =
  | "awaiting_answer"
  | "awaiting_prediction_result" // predict: answer recorded, waiting for resolve_prediction
  | "answered"
  | "skipped"
  | "deferred"
  | "reported";

/** What the browser is allowed to see. Never includes ideal_answer, rubric, or correct_index. */
export interface MomentView {
  id: string;
  sessionId: string;
  type: MomentType | "boss";
  concept: string;
  conceptCard?: string;
  question: string;
  mcOptions?: string[]; // only once MC fallback is offered
  status: MomentStatus;
  bossId?: string;
  answer?: string;
  mcChoice?: number;
  verdict?: Verdict;
  why?: string;
  correctIndex?: number; // only revealed after an MC answer
  xp?: number;
}
/**
 * Core entities persisted per user/session. See docs/design-plan.md §10.
 */
import type Anthropic from "@anthropic-ai/sdk";
import type { EngineState, Familiarity, UserSettings, BossOutcome } from "./engine";
import type { LearningMomentInput, MomentStatus, MomentType, Verdict } from "./moment";

export interface User {
  anonId: string;
  createdAt: number;
  xp: number;
  level: number;
  unlocks: { themes: string[]; soundPacks: string[] };
  settings: UserSettings;
}

export interface Intent {
  goal: string;
  familiarity: Familiarity;
  minutes: number; // session length target (default 10)
  demo: boolean; // started from the churn demo starter
}

/** Light "session sketch" generated in the background (Opus, high effort). Not a curriculum. */
export interface SessionSketch {
  title: string;
  goalSummary: string;
  novice: boolean;
  milestones: string[]; // 3-5 likely chunks of work
  conceptRadar: { concept: string; whyItMatters: string; likelyMomentType: MomentType }[];
}

export interface StoryBible {
  genre: string;
  tone: string;
  setting: string;
  protagonist: string;
  motif: string; // light theming drawn from the user's work
  arc: string[]; // planned beats
  seeds: { narrator: string; twist: string };
}

export interface StoryChapter {
  id: string;
  trigger: string; // e.g. "boss:<id>" | "wrapup"
  title: string;
  text: string;
  summary: string;
  createdAt: number;
}

export interface StoryState {
  bible?: StoryBible;
  chapters: StoryChapter[];
}

export interface Session {
  id: string;
  anonId: string;
  createdAt: number;
  title: string;
  intent: Intent;
  sketch?: SessionSketch;
  containerId?: string;
  fileIds: string[]; // files produced in this session (ownership check for /api/files/[id])
  demoFileAttached: boolean;
  status: "active" | "wrapped";
  engine: EngineState;
  rollingSummary?: string;
  story: StoryState;
}

/** Full server-side record of a moment (contains answer keys; never sent to the client as-is). */
export interface MomentRecord {
  id: string;
  sessionId: string;
  createdAt: number;
  type: MomentType | "boss";
  candidate: LearningMomentInput; // for boss questions, generated by the boss route in the same shape
  toolUseId?: string; // the learning_moment tool_use block id (work moments)
  bossId?: string;
  status: MomentStatus;
  mcOffered: boolean;
  answer?: string;
  mcChoice?: number;
  verdict?: Verdict;
  why?: string;
  missingPoints?: string[];
  xp?: number;
  answeredAt?: number;
}

export interface BossState {
  id: string;
  sessionId: string;
  name: string; // e.g. "The Overfit Bug"
  ascii: "bug" | "slime" | "ghost";
  intro: string;
  maxHp: number;
  hp: number;
  momentIds: string[];
  outcome?: BossOutcome;
  createdAt: number;
}

/** Renderable transcript item (UI history; separate from the raw API message list). */
export type TranscriptItem =
  | { kind: "user"; id: string; text: string; at: number }
  | { kind: "assistant_text"; id: string; text: string }
  | {
      kind: "code_run";
      id: string; // server_tool_use block id
      language: "bash" | "python" | "file";
      code: string;
      stdout?: string;
      stderr?: string;
      returnCode?: number;
      fileIds: string[];
    }
  | { kind: "moment"; id: string; momentId: string }
  | { kind: "prediction_reveal"; id: string; momentId: string; actualResult: string; verdict: Verdict; why: string; xp: number }
  | { kind: "milestone"; id: string; label: string }
  | { kind: "boss"; id: string; bossId: string }
  | { kind: "story"; id: string; chapterId: string }
  | { kind: "notice"; id: string; text: string };

/** Raw conversation as sent to the Claude API. */
export type ApiMessages = Anthropic.MessageParam[];

export interface SessionSummary {
  id: string;
  title: string;
  createdAt: number;
  status: Session["status"];
}

export interface AppEvent {
  at: number;
  anonId: string;
  sessionId?: string;
  name:
    | "unlock"
    | "session_created"
    | "moment_proposed"
    | "moment_gated"
    | "moment_shown"
    | "moment_answered"
    | "moment_skipped"
    | "moment_deferred"
    | "moment_reported"
    | "mc_offered"
    | "boss_started"
    | "boss_finished"
    | "session_wrapped"
    | "guardrails_changed"
    | "level_up"
    | "error";
  props?: Record<string, string | number | boolean | null>;
}
/**
 * Storage interface. Track E implements RedisStore (Upstash); MemoryStore (lib/store/memory.ts)
 * is the in-process implementation for tests and local dev without Redis.
 * Keys and TTLs: docs/design-plan.md §10 (60-day sliding TTL on user data).
 */
import type { ConceptMastery, MasteryMap } from "./engine";
import type {
  ApiMessages,
  AppEvent,
  BossState,
  MomentRecord,
  Session,
  SessionSummary,
  TranscriptItem,
  User,
} from "./session";

export type UsageScope = { kind: "anon"; id: string } | { kind: "ip"; id: string } | { kind: "global" };

export interface Store {
  getUser(anonId: string): Promise<User | null>;
  putUser(user: User): Promise<void>;

  listSessions(anonId: string): Promise<SessionSummary[]>;
  getSession(sessionId: string): Promise<Session | null>;
  putSession(session: Session): Promise<void>;

  getApiMessages(sessionId: string): Promise<ApiMessages>;
  putApiMessages(sessionId: string, messages: ApiMessages): Promise<void>;

  getTranscript(sessionId: string): Promise<TranscriptItem[]>;
  putTranscript(sessionId: string, items: TranscriptItem[]): Promise<void>;

  getMoment(sessionId: string, momentId: string): Promise<MomentRecord | null>;
  listMoments(sessionId: string): Promise<MomentRecord[]>;
  putMoment(moment: MomentRecord): Promise<void>;

  getBoss(sessionId: string, bossId: string): Promise<BossState | null>;
  putBoss(boss: BossState): Promise<void>;

  getMastery(anonId: string): Promise<MasteryMap>;
  putMastery(anonId: string, concept: string, mastery: ConceptMastery): Promise<void>;

  /** Adds spend (micro-USD) for today's date (UTC) to each scope; returns new totals in the same order. */
  addUsage(scopes: UsageScope[], microUsd: number): Promise<number[]>;
  getUsage(scopes: UsageScope[]): Promise<number[]>;

  logEvent(event: AppEvent): Promise<void>;
}
/**
 * Server → browser stream protocol for POST /api/chat.
 * Transport: newline-delimited JSON (one ChatStreamEvent per line), Content-Type application/x-ndjson.
 */
import type { MomentView, Verdict } from "./moment";
import type { LevelInfo, LevelReward } from "./engine";

export interface XpAward {
  amount: number;
  reason: string;
  level: LevelInfo;
  levelUp?: { from: number; to: number; rewards: LevelReward[] };
}

export type TurnEndReason =
  | "end_turn" // Claude finished; waiting for the user's next message
  | "awaiting_learner" // a learning moment is shown; waiting for the answer
  | "boss_due" // milestone reached and a boss should start (client calls /api/boss)
  | "refusal"
  | "max_steps"
  | "error";

export type ChatStreamEvent =
  | { type: "status"; status: "thinking" | "running_code" | "preparing_moment" }
  | { type: "text_delta"; itemId: string; text: string }
  | { type: "code_start"; itemId: string; language: "bash" | "python" | "file"; code: string }
  | { type: "code_result"; itemId: string; stdout: string; stderr: string; returnCode: number; fileIds: string[] }
  | { type: "moment"; itemId: string; moment: MomentView }
  | { type: "prediction_reveal"; itemId: string; momentId: string; actualResult: string; verdict: Verdict; why: string; xp: XpAward }
  | { type: "milestone"; itemId: string; label: string; bossDue: boolean }
  | { type: "notice"; itemId: string; text: string }
  | { type: "turn_end"; reason: TurnEndReason; detail?: string }
  | { type: "error"; message: string; retryable: boolean; code?: "rate_limited" | "spend_cap" | "bad_request" | "upstream" };
/** Server → client view mappers (shared). Never leak answer keys to the browser. */
import type { MomentView } from "@/lib/contracts/moment";
import type { BossState, MomentRecord, User } from "@/lib/contracts/session";
import type { BossView, UserView } from "@/lib/contracts/api";
import { engine } from "@/lib/engine";

export function toMomentView(m: MomentRecord): MomentView {
  const revealMC = m.mcOffered;
  return {
    id: m.id,
    sessionId: m.sessionId,
    type: m.type,
    concept: m.candidate.concept,
    conceptCard: m.candidate.concept_card,
    question: m.candidate.question,
    mcOptions: revealMC ? m.candidate.mc_fallback.options : undefined,
    status: m.status,
    bossId: m.bossId,
    answer: m.answer,
    mcChoice: m.mcChoice,
    verdict: m.verdict,
    why: m.why,
    correctIndex: m.mcChoice !== undefined ? m.candidate.mc_fallback.correct_index : undefined,
    xp: m.xp,
  };
}

export function toBossView(b: BossState, moments: MomentRecord[]): BossView {
  const current = b.momentIds.find((id) => {
    const m = moments.find((x) => x.id === id);
    return m && m.status === "awaiting_answer";
  });
  return { id: b.id, name: b.name, ascii: b.ascii, intro: b.intro, hp: b.hp, maxHp: b.maxHp, momentIds: b.momentIds, currentMomentId: current, outcome: b.outcome };
}

export function toUserView(u: User): UserView {
  return { xp: u.xp, level: engine.levelFor(u.xp), unlocks: u.unlocks, settings: u.settings };
}

