    { semi: 4, at: 0.12, dur: 0.2 },
    { semi: 7, at: 0.24, dur: 0.2 },
    { semi: 12, at: 0.36, dur: 0.35 },
    { semi: 9, at: 0.6, dur: 0.18 },
    { semi: 12, at: 0.72, dur: 0.18 },
