import ReactMarkdown, { type Components } from "react-markdown";
import remarkGfm from "remark-gfm";

/** Styles for markdown elements (no typography plugin). */
const COMPONENTS: Components = {
  p: ({ node: _n, ...p }) => <p className="my-2 first:mt-0 last:mb-0" {...p} />,
  a: ({ node: _n, ...p }) => (
    <a className="font-semibold text-primary underline underline-offset-2" target="_blank" rel="noopener noreferrer" {...p} />
  ),
  ul: ({ node: _n, ...p }) => <ul className="my-2 list-disc space-y-1 pl-6" {...p} />,
  ol: ({ node: _n, ...p }) => <ol className="my-2 list-decimal space-y-1 pl-6" {...p} />,
  h1: ({ node: _n, ...p }) => <h3 className="mt-4 mb-2 text-lg font-bold" {...p} />,
  h2: ({ node: _n, ...p }) => <h3 className="mt-4 mb-2 text-lg font-bold" {...p} />,
  h3: ({ node: _n, ...p }) => <h4 className="mt-3 mb-1 font-bold" {...p} />,
  blockquote: ({ node: _n, ...p }) => <blockquote className="my-2 border-l-4 border-border pl-3 text-muted" {...p} />,
  pre: ({ node: _n, ...p }) => (
    <pre className="my-3 overflow-x-auto rounded-xl bg-surface-2 p-3 font-mono text-sm leading-relaxed" {...p} />
  ),
  code: ({ node: _n, className, ...p }) =>
    className ? (
      <code className={`font-mono ${className}`} {...p} />
    ) : (
      <code className="rounded-md bg-surface-2 px-1.5 py-0.5 font-mono text-[0.9em]" {...p} />
    ),
  table: ({ node: _n, ...p }) => (
    <div className="my-3 overflow-x-auto">
      <table className="w-full border-collapse text-sm" {...p} />
    </div>
  ),
  th: ({ node: _n, ...p }) => <th className="border-b border-border px-2 py-1 text-left font-bold" {...p} />,
  td: ({ node: _n, ...p }) => <td className="border-b border-border px-2 py-1" {...p} />,
  img: ({ node: _n, alt }) => <span className="text-muted">[image: {alt}]</span>,
};

/** Safe markdown: raw HTML is skipped and react-markdown's default URL sanitizer applies. */
export function Markdown({ children, className = "" }: { children: string; className?: string }) {
  return (
    <div className={`leading-relaxed break-words ${className}`}>
      <ReactMarkdown remarkPlugins={[remarkGfm]} skipHtml components={COMPONENTS}>
        {children}
      </ReactMarkdown>
    </div>
  );
}

