        <div className="space-y-4">
          <OptionResults moment={moment} />
          {moment.verdict && <Feedback verdict={moment.verdict} why={moment.why} xpAmount={xpAmount} big={big} />}
        </div>
      );
    case "answered":
      return (
        <div className="space-y-4">
          {moment.answer && <YourAnswer text={moment.answer} />}
          {moment.verdict && <Feedback verdict={moment.verdict} why={moment.why} xpAmount={xpAmount} big={big} />}
        </div>
      );
    default:
      return null;
