      {onResetData && (
        <Section title="Your data">
          {confirmReset ? (
            <div className="space-y-3 rounded-2xl bg-surface-2 p-3">
              <p className="text-sm">This clears your XP, unlocks, and past sessions on this browser. Are you sure?</p>
              <div className="flex gap-2">
