        open={drawer}
        onClose={() => setDrawer(false)}
        settings={settings}
        level={level.level}
        unlocks={UNLOCKS}
        onChange={patch}
        sessions={SESSIONS}
        currentSessionId="s1"
        onOpenSession={noop}
        onResetData={noop}
      />
      {toast && (
        <LevelUpToast
          from={2}
          to={3}
          rewards={[
            { level: 3, kind: "theme", id: "sunset", label: "Sunset theme" },
            { level: 3, kind: "sound_pack", id: "marimba", label: "Marimba sound pack" },
