                <div className="h-10 rounded-xl border border-border" style={{ background: `var(--${tok})` }} />
                <span className="text-muted">{tok}</span>
              </div>
            ))}
          </div>
        </Section>

        <Section id="sounds" title="Sounds">
          <SoundBoard settings={settings} patch={patch} />
