      case "skip":
        return setMoment((m) => ({ ...m, status: "skipped" }));
      case "defer":
        return setMoment((m) => ({ ...m, status: "deferred" }));
      case "report":
        return setMoment((m) => ({ ...m, status: "reported" }));
    }
  }
  return { moment, grading, act, reset: () => { setMoment(initial); setGrading(false); } };
}

